// ============================================================================
// Differential vectors for `parseArgs` (TS `cli/args.ts`), landed with 4g-1.
//
// args-corpus.json is generated by tools/gen-args-corpus.mjs from a verbatim
// transcription of the TypeScript `parseArgs` (plus `getToolListError` /
// `isToolModifier` from settings-manager.ts): every argv array from
// test/args.test.ts, the boundary cases that suite leaves implicit, and 400
// seeded fuzz permutations over a flag/value token pool. Each case records the
// TS result in the shape of the TS `Args` interface, and this test replays the
// same argv through the C# parser and compares field by field.
//
// The generator is gitignored (tools/); the corpus is committed, same as the
// other *-corpus.json slices.
// ============================================================================

using System.Text.Json;
using Pi.CodingAgent.Cli;
using Pi.CodingAgent.Core;
using Xunit;

namespace Pi.CodingAgent.Tests;

public sealed class CliArgsCorpusTests
{
    public static TheoryData<string> Cases { get; } = LoadCases();

    private static TheoryData<string> LoadCases()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "args-corpus.json");
        Assert.True(File.Exists(path), $"missing corpus file at {path}");
        using var document = JsonDocument.Parse(File.ReadAllText(path));
        var data = new TheoryData<string>();
        foreach (var testCase in document.RootElement.GetProperty("cases").EnumerateArray())
        {
            data.Add(testCase.GetRawText());
        }

        return data;
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void MatchesTypeScriptReference(string caseJson)
    {
        using var document = JsonDocument.Parse(caseJson);
        var root = document.RootElement;
        var input = root.GetProperty("input").EnumerateArray().Select(e => e.GetString()!).ToArray();
        var expected = root.GetProperty("expected");

        var actual = CliArgs.Parse(input);
        var label = $"parseArgs([{string.Join(", ", input.Select(Quote))}])";

        ExpectString(expected, "provider", actual.Provider, label);
        ExpectString(expected, "model", actual.Model, label);
        ExpectString(expected, "apiKey", actual.ApiKey, label);
        ExpectString(expected, "systemPrompt", actual.SystemPrompt, label);
        ExpectList(expected, "appendSystemPrompt", actual.AppendSystemPrompt, label);
        ExpectThinking(expected, actual.Thinking, label);
        ExpectBool(expected, "continue", actual.Continue, label);
        ExpectBool(expected, "resume", actual.Resume, label);
        ExpectBool(expected, "help", actual.Help, label);
        ExpectBool(expected, "version", actual.Version, label);
        ExpectMode(expected, actual.Mode, label);
        ExpectString(expected, "name", actual.Name, label);
        ExpectBool(expected, "noSession", actual.NoSession, label);
        ExpectString(expected, "session", actual.Session, label);
        ExpectString(expected, "sessionId", actual.SessionId, label);
        ExpectString(expected, "fork", actual.Fork, label);
        ExpectString(expected, "sessionDir", actual.SessionDir, label);
        ExpectList(expected, "models", actual.Models, label);
        ExpectList(expected, "tools", actual.Tools, label);
        ExpectList(expected, "excludeTools", actual.ExcludeTools, label);
        ExpectBool(expected, "noTools", actual.NoTools, label);
        ExpectBool(expected, "noBuiltinTools", actual.NoBuiltinTools, label);
        ExpectList(expected, "extensions", actual.Extensions, label);
        ExpectBool(expected, "noExtensions", actual.NoExtensions, label);
        ExpectBool(expected, "noMcp", actual.NoMcp, label);
        ExpectBool(expected, "print", actual.Print, label);
        ExpectString(expected, "export", actual.Export, label);
        ExpectBool(expected, "noSkills", actual.NoSkills, label);
        ExpectList(expected, "skills", actual.Skills, label);
        ExpectList(expected, "promptTemplates", actual.PromptTemplates, label);
        ExpectBool(expected, "noPromptTemplates", actual.NoPromptTemplates, label);
        ExpectList(expected, "themes", actual.Themes, label);
        ExpectString(expected, "useTheme", actual.UseTheme, label);
        ExpectBool(expected, "noThemes", actual.NoThemes, label);
        ExpectBool(expected, "noContextFiles", actual.NoContextFiles, label);
        ExpectListModels(expected, actual, label);
        ExpectBool(expected, "offline", actual.Offline, label);
        ExpectTuiMode(expected, actual.TuiMode, label);
        ExpectBool(expected, "verbose", actual.Verbose, label);
        ExpectBool(expected, "projectTrustOverride", actual.ProjectTrustOverride, label);
        ExpectList(expected, "messages", actual.Messages, label);
        ExpectList(expected, "fileArgs", actual.FileArgs, label);
        ExpectUnknownFlags(expected, actual.UnknownFlags, label);
        ExpectDiagnostics(expected, actual.Diagnostics, label);
    }

    // ------------------------------------------------------------------ helpers

    private static string Quote(string value) => $"\"{value.Replace("\"", "\\\"", StringComparison.Ordinal)}\"";

    private static void ExpectBool(JsonElement expected, string name, bool? actual, string label)
    {
        var value = expected.GetProperty(name);
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected {name} absent, got {actual}");
            return;
        }

        Assert.True(value.ValueKind == JsonValueKind.True || value.ValueKind == JsonValueKind.False,
            $"{label}: expected {name} to be a boolean, got {value}");
        Assert.Equal(value.GetBoolean(), actual);
    }

    private static void ExpectString(JsonElement expected, string name, string? actual, string label)
    {
        var value = expected.GetProperty(name);
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected {name} absent, got {actual}");
            return;
        }

        Assert.Equal(value.GetString(), actual);
    }

    private static void ExpectList(JsonElement expected, string name, List<string>? actual, string label)
    {
        var value = expected.GetProperty(name);
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected {name} absent, got {actual}");
            return;
        }

        Assert.Equal(value.EnumerateArray().Select(e => e.GetString()!).ToArray(), actual);
    }

    private static void ExpectThinking(JsonElement expected, Pi.Ai.Types.ThinkingLevel? actual, string label)
    {
        var value = expected.GetProperty("thinking");
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected thinking absent, got {actual}");
            return;
        }

        Assert.Equal(ThinkingLevels.Parse(value.GetString()), actual);
    }

    private static void ExpectMode(JsonElement expected, CliMode? actual, string label)
    {
        var value = expected.GetProperty("mode");
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected mode absent, got {actual}");
            return;
        }

        Assert.Equal(CliModeText.Parse(value.GetString()), actual);
    }

    private static void ExpectTuiMode(JsonElement expected, Pi.Tui.TuiMode? actual, string label)
    {
        var value = expected.GetProperty("tuiMode");
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual is null, $"{label}: expected tuiMode absent, got {actual}");
            return;
        }

        Assert.Equal(value.GetString() == "regular" ? Pi.Tui.TuiMode.Regular : Pi.Tui.TuiMode.Fullscreen, actual);
    }

    private static void ExpectListModels(JsonElement expected, Args actual, string label)
    {
        // TS `listModels?: string | true` is split into ListModels + ListModelsSearch.
        var value = expected.GetProperty("listModels");
        if (value.ValueKind == JsonValueKind.Null)
        {
            Assert.True(actual.ListModels is null, $"{label}: expected listModels absent, got {actual.ListModels}");
            Assert.True(actual.ListModelsSearch is null, $"{label}: expected no listModels search");
            return;
        }

        Assert.True(actual.ListModels == true, $"{label}: expected listModels present, got {actual.ListModels}");
        if (value.ValueKind == JsonValueKind.String)
        {
            Assert.Equal(value.GetString(), actual.ListModelsSearch);
        }
        else
        {
            Assert.True(value.ValueKind == JsonValueKind.True, $"{label}: unexpected listModels {value}");
            Assert.True(actual.ListModelsSearch is null,
                $"{label}: expected no listModels search, got {actual.ListModelsSearch}");
        }
    }

    private static void ExpectUnknownFlags(JsonElement expected, Dictionary<string, object> actual, string label)
    {
        var value = expected.GetProperty("unknownFlags");
        var entries = value.EnumerateObject().ToArray();
        Assert.Equal(entries.Length, actual.Count);
        foreach (var entry in entries)
        {
            Assert.True(actual.TryGetValue(entry.Name, out var flagValue),
                $"{label}: expected unknownFlags to contain \"{entry.Name}\"");
            if (entry.Value.ValueKind == JsonValueKind.String)
            {
                Assert.Equal(entry.Value.GetString(), flagValue);
            }
            else
            {
                Assert.True(entry.Value.ValueKind == JsonValueKind.True,
                    $"{label}: unknownFlags[\"{entry.Name}\"] expected boolean or string, got {entry.Value}");
                Assert.True(Assert.IsType<bool>(flagValue));
            }
        }
    }

    private static void ExpectDiagnostics(JsonElement expected, List<AgentSessionRuntimeDiagnostic> actual, string label)
    {
        var value = expected.GetProperty("diagnostics");
        var entries = value.EnumerateArray().ToArray();
        Assert.Equal(entries.Length, actual.Count);
        for (var i = 0; i < entries.Length; i++)
        {
            var type = entries[i].GetProperty("type").GetString()!;
            var message = entries[i].GetProperty("message").GetString()!;
            Assert.Equal(type == "error" ? AgentSessionDiagnosticType.Error : AgentSessionDiagnosticType.Warning,
                actual[i].Type);
            Assert.Equal(message, actual[i].Message);
        }
    }
}
